import itertools


def _route_solver(exact, minimum_duration):
    def solve(data):
        required = data.get("required", [])
        bit = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        source = data["source"]
        initial_mask = bit.get(source, 0)
        start = data["start"]
        coupons = data["coupons"]
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        # The state retains both visited requirements and coupon usage.
        initial = (source, initial_mask, 0)
        dist = {initial: start}
        queue = [(start, source, initial_mask, 0)]
        while queue:
            arrival, node, mask, used = heapq.heappop(queue)
            state = (node, mask, used)
            if dist.get(state) != arrival:
                continue
            if (node == data["target"] and mask == full and
                    (not exact or used == coupons)):
                return {"arrival": arrival}
            for edge in graph[node]:
                depart = max(arrival, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], used)]
                if used < coupons:
                    duration = max(minimum_duration,
                                   edge["duration"] - edge.get("discount", 0))
                    options.append((duration, used + 1))
                for duration, next_used in options:
                    next_time = depart + duration
                    if next_time > data["deadline"]:
                        continue
                    next_node = edge["v"]
                    next_mask = mask | bit.get(next_node, 0)
                    next_state = (next_node, next_mask, next_used)
                    if next_time < dist.get(next_state, float("inf")):
                        dist[next_state] = next_time
                        heapq.heappush(queue, (next_time, next_node,
                                               next_mask, next_used))
        return {"arrival": None}
    return solve


def _build_component_06():
    def rounded(numerator, denominator, mode):
        if mode == "half_up":
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        chosen = {}
        for position, event in enumerate(data["events"]):
            if event.get("sequence", 0) > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            key = (event.get("sequence", 0), event.get("revision", 0), position)
            if event_id not in chosen or key > chosen[event_id][0]:
                chosen[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in chosen.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, mode)
            tax = rounded(raw * event.get("tax_bp", 0), 10000, mode)
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            key = (event.get("account", "default") + "|" +
                   event.get("currency", "USD"))
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = list(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})

        choices = []
        for name in names:
            versions = sorted(row["version"] for row in packages[name]
                              if row["version"] not in blocked.get(name, [])
                              and (name not in pins or row["version"] == pins[name]))
            choices.append([None] + versions)

        best_vector = None
        best = None
        for selection in itertools.product(*choices):
            installed = {name: version for name, version in zip(names, selection)
                         if version is not None}
            valid = True
            for name, bounds in data["roots"].items():
                version = installed.get(name)
                if version is None or not bounds[0] <= version <= bounds[1]:
                    valid = False
                    break
            if not valid:
                continue

            rows = {}
            for name, version in installed.items():
                rows[name] = next(row for row in packages[name]
                                  if row["version"] == version)

            graph = {}
            for name, row in rows.items():
                active = []
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    dep_version = installed.get(dep["name"])
                    if (dep_version is None or
                            not dep["min"] <= dep_version <= dep["max"]):
                        valid = False
                        break
                    active.append(dep["name"])
                graph[name] = active
                if not valid:
                    break
            if not valid:
                continue

            reachable = set()
            stack = list(data["roots"])
            while stack:
                name = stack.pop()
                if name in reachable:
                    continue
                reachable.add(name)
                stack.extend(graph[name])
            if reachable != set(installed):
                continue

            visiting, finished = set(), set()
            def acyclic(name):
                if name in visiting:
                    return False
                if name in finished:
                    return True
                visiting.add(name)
                if any(not acyclic(child) for child in graph[name]):
                    return False
                visiting.remove(name)
                finished.add(name)
                return True

            if any(not acyclic(name) for name in reachable):
                continue

            vector = tuple(installed.get(name, -1)
                           for name in sorted(names, reverse=True))
            if best_vector is None or vector > best_vector:
                best_vector, best = vector, installed

        if best is None:
            return {"error": "unsatisfiable"}
        return {"versions": best}
    return solve


def _build_component_08():
    def allowed(selected, data):
        ids = {job["id"] for job in selected}
        if not set(data.get("mandatory", [])).issubset(ids):
            return False
        counts = {}
        for job in selected:
            group = job["group"]
            counts[group] = counts.get(group, 0) + 1
        for group, bounds in data.get("quotas", {}).items():
            if not bounds[0] <= counts.get(group, 0) <= bounds[1]:
                return False
        intervals = sorted((job["start"], job["end"]) for job in selected)
        active_ends = []
        for start, end in intervals:
            while active_ends and active_ends[0] <= start:
                heapq.heappop(active_ends)
            heapq.heappush(active_ends, end)
            if len(active_ends) > 2:
                return False
        return True

    def solve(data):
        blocked = set(data.get("blocked", []))
        jobs = [job for job in data["jobs"] if job["id"] not in blocked]
        best_value = None
        best_ids = None
        for selected in itertools.combinations(jobs, data["k"]):
            if not allowed(selected, data):
                continue
            value = sum(job["value"] for job in selected)
            ids = sorted(job["id"] for job in selected)
            if (best_value is None or value > best_value or
                    (value == best_value and ids < best_ids)):
                best_value, best_ids = value, ids
        if best_value is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


